'use client'
import { createContext, useEffect, useId, useImperativeHandle, useRef, type ReactNode, type Ref } from 'react'
import { useMenu } from '@/react/hooks/useMenu'
import { cn } from '@/react/lib/cn'

// shadcn's dropdown menu in the brand: a button that opens a short list of actions or choices on the #171717 overlay
// surface, a neutral hairline, the 8px corner, no shadow, 4px inside; rows are MenuItem (shadcn's DropdownMenuItem),
// with MenuLabel and MenuSeparator between groups. It comes in over 200ms (a 4px drop and a touch of scale from its
// trigger's edge, ease-out), leaves at once, and does not animate when opened from the keyboard, which is how menus
// are opened most. Arrows, Home, End, Escape, Tab and a click outside are handled (useMenu). The trigger's content is
// `trigger` (a node, or a function of `open`), drawn as a small secondary button unless `triggerClass` says
// otherwise. `defaultOpen` opens it with the page; `ref` gets { open, show, close }; `onOpenChange` hears it.
export const MenuClose = createContext<() => void>(() => {})

export interface DropdownMenuHandle { open: boolean, show: (focus?: 'first' | 'last' | 'none') => void, close: (refocus?: boolean) => void }
export interface DropdownMenuProps {
  /** The menu's name for assistive tech. */
  label: string
  /** Opens upward. */
  up?: boolean
  /** The panel's edge: start, or end to line up with the trigger's end. */
  align?: 'start' | 'end'
  /** The panel's width. */
  width?: string
  /** Moves the panel in from its edge. */
  offset?: string
  /** Classes for the trigger button, in place of the small secondary button. */
  triggerClass?: string
  /** The trigger's name, when its content has none (an icon). */
  triggerLabel?: string
  /** The trigger's content, or a function of whether it is open. */
  trigger?: ReactNode | ((open: boolean) => ReactNode)
  /** Opens with the page. */
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  className?: string
  children?: ReactNode
  ref?: Ref<DropdownMenuHandle>
}

export const MENU_TRIGGER = 'inline-flex h-control-sm cursor-pointer items-center gap-1.5 rounded-control bg-action-secondary px-3 type-ui-strong text-action-secondary-fg transition-[background-color] duration-150 ease-standard hover:bg-action-secondary-hover aria-expanded:bg-action-secondary-hover max-md:h-control-touch'

export function DropdownMenu({ label, up, align = 'start', width = '240px', offset = '0px', triggerClass, triggerLabel, trigger: triggerContent, defaultOpen, onOpenChange, className, children, ref }: DropdownMenuProps) {
  const { open, root, trigger, show, close, toggle, onTriggerKey, onMenuKey } = useMenu(defaultOpen)
  const report = useRef(onOpenChange)
  report.current = onOpenChange
  const was = useRef(open)
  useEffect(() => {
    if (was.current === open) return
    was.current = open
    report.current?.(open)
  }, [open])
  useImperativeHandle(ref, () => ({ open, show, close }), [open, show, close])
  const id = `menu-${useId()}`
  return (
    <MenuClose.Provider value={() => close(true)}>
      <style href="ds-dropdown-menu" precedence="ds">{css}</style>
      <div data-ds="dropdown-menu" ref={root} className={cn('relative inline-block', className)}>
        <button
          ref={trigger}
          type="button"
          className={triggerClass ?? MENU_TRIGGER}
          aria-haspopup="menu"
          aria-expanded={open}
          aria-controls={id}
          aria-label={triggerLabel}
          onClick={toggle}
          onKeyDown={onTriggerKey}
        >
          {typeof triggerContent === 'function' ? triggerContent(open) : triggerContent}
        </button>
        {open && (
          <div
            id={id}
            className="ds-menu"
            data-up={up || undefined}
            data-align={align}
            style={{ width, [align === 'end' ? 'right' : 'left']: offset, [up ? 'bottom' : 'top']: 'calc(100% + 4px)' }}
            role="menu"
            aria-label={label}
            onKeyDown={onMenuKey}
          >
            {children}
          </div>
        )}
      </div>
    </MenuClose.Provider>
  )
}

export default DropdownMenu

const css = `
.ds-menu { position: absolute; z-index: 40; display: flex; max-width: calc(100vw - 16px); flex-direction: column; padding: var(--ds-space-xs); border: var(--ds-border-hairline) solid var(--ds-color-edge); border-radius: var(--ds-radius-container); background: var(--ds-color-surface-raised); color: var(--ds-color-fg); transform-origin: top left; animation: ds-menu-in var(--ds-duration-enter) var(--ds-easing-out) both; scroll-margin: 8px; }
.ds-menu[data-align="end"] { transform-origin: top right; }
.ds-menu[data-up] { transform-origin: bottom left; animation-name: ds-menu-up; }
.ds-menu[data-up][data-align="end"] { transform-origin: bottom right; }
/* Opened from the keyboard, focus lands on a row at once: no animation. */
.ds-menu:has(:focus-visible) { animation: none; }
.ds-menu > * { flex-shrink: 0; }
@keyframes ds-menu-in { from { opacity: 0; transform: translateY(-4px) scale(0.98); } }
@keyframes ds-menu-up { from { opacity: 0; transform: translateY(4px) scale(0.98); } }
@media (prefers-reduced-motion: reduce) { .ds-menu, .ds-menu[data-up] { animation-name: ds-menu-fade; } }
@keyframes ds-menu-fade { from { opacity: 0; } }
`

'use client'
import { useContext, type ReactNode } from 'react'
import { MenuClose } from '@/react/components/ui/DropdownMenu'

// One row of a dropdown or context menu: 32px (44px on phones), DM Sans 14px, a 4px corner inside the panel's 8px. The
// row under the pointer or focus takes a #262626 fill (150ms, hover only where a pointer hovers). `current` sets it in
// Medium; `danger` is the red for leaving or deleting. Put a 16px Lucide icon first (muted), a shortcut or a check
// last. Choosing it calls `onSelect` and closes the menu, unless `keepOpen`. `role` and `aria-checked` make it a radio
// or checkbox row (role="menuitemradio" aria-checked={picked}).
export interface MenuItemProps {
  /** Renders a link. */
  href?: string
  /** The current choice, in Medium. */
  current?: boolean
  /** The red for leaving or deleting. */
  danger?: boolean
  disabled?: boolean
  /** Choosing it leaves the menu open. */
  keepOpen?: boolean
  onSelect?: () => void
  role?: 'menuitem' | 'menuitemradio' | 'menuitemcheckbox'
  'aria-checked'?: boolean
  className?: string
  children?: ReactNode
}

export const MENU_ITEM = 'flex h-control-sm w-full shrink-0 cursor-pointer items-center gap-2 rounded-ds-sm px-2 text-left type-ui text-fg outline-none transition-[background-color] duration-150 ease-standard hover:bg-ds-neutral-4 focus-visible:bg-ds-neutral-4 aria-[current=true]:font-medium disabled:cursor-not-allowed disabled:text-fg-faint disabled:hover:bg-transparent data-danger:text-fg-danger data-danger:hover:bg-surface-danger data-danger:focus-visible:bg-surface-danger max-md:h-auto max-md:min-h-control-touch'

export function MenuItem({ href, current, danger, disabled, keepOpen, onSelect, role = 'menuitem', 'aria-checked': checked, className, children }: MenuItemProps) {
  const close = useContext(MenuClose)
  function choose() {
    onSelect?.()
    if (!keepOpen) close()
  }
  const shared = { role, 'aria-checked': checked, className: className ? `${MENU_ITEM} ${className}` : MENU_ITEM, 'aria-current': current ? 'true' as const : undefined, 'data-danger': danger || undefined, onClick: choose }
  return href ? <a data-ds="menu-item" href={href} {...shared}>{children}</a> : <button data-ds="menu-item" type="button" disabled={disabled} {...shared}>{children}</button>
}

/** shadcn's name for it. */
export { MenuItem as DropdownMenuItem }

export default MenuItem

import type { ReactNode } from 'react'

// A group's name in a dropdown or context menu: a DM Sans Medium label in capitals with 6% tracking, muted.
export function MenuLabel({ children }: { children?: ReactNode }) {
  return <p data-ds="menu-label" className="flex items-center justify-between gap-2 px-2 pt-2 pb-1 type-label text-fg-muted">{children}</p>
}

/** shadcn's name for it. */
export { MenuLabel as DropdownMenuLabel }

export default MenuLabel

// A neutral hairline between a menu's groups, edge to edge.
export function MenuSeparator() {
  return <div data-ds="menu-separator" className="-mx-1 my-1 h-px bg-edge" role="separator" />
}

/** shadcn's name for it. */
export { MenuSeparator as DropdownMenuSeparator }

export default MenuSeparator

'use client'
import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from 'react'

/**
 * A menu button's behavior: it opens on click, arrows move between items (opening the menu on their end of it from the
 * button), Home and End jump, Escape closes and returns focus to the button, Tab and a click outside close it.
 */
export function useMenu(initial = false) {
  const [open, setOpen] = useState(initial)
  const root = useRef<HTMLDivElement | null>(null)
  const trigger = useRef<HTMLButtonElement | null>(null)
  const pending = useRef<'first' | 'last' | 'none' | null>(null)
  // Each show() renders, so an arrow on the open menu's button still focuses a row (Vue's nextTick runs either way).
  const [, setShown] = useState(0)

  const items = () => [...(root.current?.querySelectorAll<HTMLElement>('[role^="menuitem"]:not([disabled])') ?? [])]

  // After the menu renders: scroll it into view and focus the row asked for (Vue's nextTick).
  useEffect(() => {
    if (!open || !pending.current) return
    const focus = pending.current
    pending.current = null
    // Opened at the fold it would land out of sight, and the button would seem to do nothing.
    items()[0]?.closest('[role="menu"]')?.scrollIntoView({ block: 'nearest' })
    if (focus === 'none') return
    const list = items()
    ;(focus === 'last' ? list.at(-1) : list[0])?.focus()
  })

  const show = useCallback((focus: 'first' | 'last' | 'none' = 'first') => {
    pending.current = focus
    setOpen(true)
    setShown(n => n + 1)
  }, [])
  const close = useCallback((refocus = false) => {
    setOpen(false)
    if (refocus) trigger.current?.focus()
  }, [])
  function toggle() {
    if (open) close()
    else show('none')
  }
  function onTriggerKey(event: KeyboardEvent) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      show(event.key === 'ArrowDown' ? 'first' : 'last')
    }
    else if (event.key === 'Escape' && open) {
      event.preventDefault()
      close(true)
    }
  }
  function onMenuKey(event: KeyboardEvent) {
    const list = items()
    const at = list.indexOf(document.activeElement as HTMLElement)
    if (event.key === 'Escape') {
      event.preventDefault()
      close(true)
    }
    else if (event.key === 'Tab') {
      close()
    }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      const step = event.key === 'ArrowDown' ? 1 : -1
      list[(at + step + list.length) % list.length]?.focus()
    }
    else if (event.key === 'Home' || event.key === 'End') {
      event.preventDefault()
      ;(event.key === 'Home' ? list[0] : list.at(-1))?.focus()
    }
  }
  useEffect(() => {
    function outside(event: PointerEvent) {
      if (root.current && !root.current.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', outside)
    return () => document.removeEventListener('pointerdown', outside)
  }, [])

  return { open, root, trigger, show, close, toggle, onTriggerKey, onMenuKey }
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

